-- ── 4. triggers ───────────────────────────────────────────────────

DROP TRIGGER IF EXISTS "AssistantThread_scope_guard" ON "AssistantThread";
CREATE TRIGGER "AssistantThread_scope_guard" BEFORE INSERT OR UPDATE OF "clinicId", "patientId", "assessmentId" ON "AssistantThread" FOR EACH ROW EXECUTE FUNCTION public.stage1_validate_thread_scope();

DROP TRIGGER IF EXISTS "KnowledgeDocument_hair_publication_guard" ON "KnowledgeDocument";
CREATE TRIGGER "KnowledgeDocument_hair_publication_guard" BEFORE INSERT OR UPDATE ON "KnowledgeDocument" FOR EACH ROW EXECUTE FUNCTION public.enforce_hair_publication();

DROP TRIGGER IF EXISTS "KnowledgeClaim_hair_publication_guard" ON "KnowledgeClaim";
CREATE TRIGGER "KnowledgeClaim_hair_publication_guard" BEFORE INSERT OR UPDATE ON "KnowledgeClaim" FOR EACH ROW EXECUTE FUNCTION public.enforce_hair_claim_publication();

DROP TRIGGER IF EXISTS "KnowledgeDocumentVersion_hair_publication_guard" ON "KnowledgeDocumentVersion";
CREATE TRIGGER "KnowledgeDocumentVersion_hair_publication_guard" BEFORE INSERT OR UPDATE ON "KnowledgeDocumentVersion" FOR EACH ROW EXECUTE FUNCTION public.enforce_hair_version_publication();

DROP TRIGGER IF EXISTS "KnowledgeChunk_hair_publication_guard" ON "KnowledgeChunk";
CREATE TRIGGER "KnowledgeChunk_hair_publication_guard" BEFORE INSERT OR UPDATE ON "KnowledgeChunk" FOR EACH ROW EXECUTE FUNCTION public.enforce_hair_chunk_publication();

DROP TRIGGER IF EXISTS "StructuredFactRecord_publication_guard" ON "StructuredFactRecord";
CREATE TRIGGER "StructuredFactRecord_publication_guard" BEFORE INSERT OR UPDATE ON "StructuredFactRecord" FOR EACH ROW EXECUTE FUNCTION public.enforce_structured_fact_publication();


-- ── 5. grants ─────────────────────────────────────────────────────

GRANT EXECUTE ON FUNCTION public.jwt_user_role()                TO authenticated, anon, service_role;
GRANT EXECUTE ON FUNCTION public.jwt_clinic_id()                TO authenticated, anon, service_role;
GRANT EXECUTE ON FUNCTION public.jwt_is_super_admin()           TO authenticated, anon, service_role;
GRANT EXECUTE ON FUNCTION public.jwt_is_clinic_member(text)     TO authenticated, anon, service_role;
GRANT SELECT ON "Product", "ProductAlias", "ProductPriceVersion", "ProductPrice", "Ingredient", "ProductIngredient", "Kit", "KitAlias", "KitVersion", "KitProduct", "KitPrice", "KitSchedule" TO authenticated;
GRANT SELECT ON "KnowledgeDocument", "KnowledgeDocumentVersion", "KnowledgeChunk", "KnowledgeApproval", "KnowledgeConflict", "IngestionRun" TO authenticated;
GRANT SELECT, INSERT, UPDATE ON "AssistantThread" TO authenticated;
GRANT SELECT ON "AssistantMessage", "AssistantToolCall", "AssistantCitation", "AssistantSafetyEvent", "AssistantEscalation", "AdverseEvent" TO authenticated;
GRANT SELECT, INSERT ON "AssistantFeedback" TO authenticated;
GRANT ALL ON "Product", "ProductAlias", "ProductPriceVersion", "ProductPrice", "Ingredient", "ProductIngredient", "Kit", "KitAlias", "KitVersion", "KitProduct", "KitPrice", "KitSchedule", "KnowledgeDocument", "KnowledgeDocumentVersion", "KnowledgeChunk", "KnowledgeApproval", "KnowledgeConflict", "IngestionRun", "AssistantThread", "AssistantMessage", "AssistantToolCall", "AssistantCitation", "AssistantSafetyEvent", "AssistantFeedback", "AssistantEscalation", "AdverseEvent" TO service_role;
GRANT SELECT ON "KnowledgeSourceFile", "KnowledgeIngestionStage", "KnowledgeClaim" TO authenticated;
GRANT ALL ON "KnowledgeSourceFile", "KnowledgeIngestionStage", "KnowledgeClaim" TO service_role;
GRANT SELECT ON "ClaimEvidence", "StructuredFactRecord", "KnowledgeReviewAction" TO authenticated;
GRANT ALL ON "ClaimEvidence", "StructuredFactRecord", "KnowledgeReviewAction" TO service_role;

